    def query_pk_new(self):
        
        i = random.randint(0,9)
        if i == 1:
            self.fun_pk_interp(self.db,'interp','')
            self.multiple_agg_groupby(self.db,1)  
            self.fun_pk_twa(self.db,'derivative',',1s,0')      
        elif i == 2:
            self.fun_pk_diff(self.db,'diff','')
            #self.fun_pk_twa(self.db,'twa','')
            self.fun_pk_twa(self.db,'derivative',',1s,1') 
            #self.tdCreateData.dropandcreateDB_random_pk("%s" % self.db, 1 ,'no','yes','yes')   
        elif i == 3:
            self.tdCreateData.dropandcreateDB_random_pk("%s" % self.db, 1 ,'no','yes','yes') 
            #self.fun_pk_twa(self.db,'irate','')
            self.fun_pk_unique(self.db,'unique','')
            self.fun_pk_last_init(self.db,'last','')  
            self.fun_pk_last(self.db,'last','') 
        elif i == 4:
            self.fun_pk_last(self.db,'last_row','') 
            #self.tdCreateData.dropandcreateDB_random_pk("%s" % self.db, 1 ,'no','yes','yes') 
            self.fun_pk_first(self.db,'first','') 
            self.count_pk(self.db,1) #pass         
        elif i == 5:
            self.query_pk_fun(self.db,'') 
            self.touying_pk_1(self.db,1)  
        elif i == 6:
            self.touying_pk_where(self.db,'') 
            self.touying_pk_where(self.db,'tags') 
            self.touying_pk_where(self.db,'distinct') 
            self.tdCreateData.dropandcreateDB_random_pk("%s" % self.db, 1 ,'no','yes','yes')  
        else: 
            self.touying_pk_asc(self.db,'') 
            self.tdCreateData.dropandcreateDB_random_pk("%s" % self.db, 1 ,'no','yes','yes') 
            self.touying_pk_asc(self.db,'tags')  
            self.touying_pk_asc(self.db,'distinct')  
    
    def query_pk_thread(self):
        
        t11 = threading.Thread(target=self.query_pk_new)
        t11.start()       
        t12 = threading.Thread(target=self.query_pk_new)
        t12.start()        
        t13 = threading.Thread(target=self.query_pk_new)
        t13.start()
        t14 = threading.Thread(target=self.query_pk_new)
        t14.start()       
        t15 = threading.Thread(target=self.query_pk_new)
        t15.start()        
        t16 = threading.Thread(target=self.query_pk_new)
        t16.start()
        t17 = threading.Thread(target=self.query_pk_new)
        t17.start()       
        t18 = threading.Thread(target=self.query_pk_new)
        t18.start()        
        t19 = threading.Thread(target=self.query_pk_new)
        t19.start()      
        t20 = threading.Thread(target=self.query_pk_new)
        t20.start()
        
        t11.join()
        t12.join()
        t13.join()
        t14.join()
        t15.join()
        t16.join()
        t17.join()
        t18.join()
        t19.join()
        t20.join()
           
                
