    def run(self)-> bool:
        startTime = time.time() 
        
        self.data_create(self.db) 
        
        
        #self.query_pk(self.db,1) 
        while 1:
            self.query_pk_thread()
        
        
        endTime = time.time()
        
        self.logger.info("total time %ds" % (endTime - startTime))
